wait_line_reach
        lda RASTER
        cmp #$fe
        bne wait_line_reach
wait_line_leave
        lda RASTER
        cmp #$fe
        beq wait_line_leave
        dey
        bne wait_line_reach
        dex
        bne wait_frames_x6
        rts
; After a one-player win: counts the clock down second by second and adds 100 points per second, with a 6-frame pause. Called by bout_1p_exchanges.
time_bonus_count
        lda time_up
        bne time_bonus_exit
time_bonus_loop
        jsr timer_tick                  ; Runs the clock without a frame wait up to the next whole second.
        lda timer_frames
        cmp #$32
        bne time_bonus_loop
        ldx #$09
        jsr score_add_100
        ldx #$01
        jsr wait_frames_x6
        lda time_up
        beq time_bonus_loop
time_bonus_exit
        rts
